# --- judge response parsers (upstream _parse_response, verbatim but for the noted edits) ---

def parse_keyword(response: str | None) -> str | int | bool | None:
    if response is None:
        return None
    lines = response.strip().splitlines()
    if len(lines) > 0:
        return normalize_text(lines[0].strip())
    else:
        return None


def parse_simple_qa(response: str | None) -> str | int | bool | None:
    if response is None:
        return -1
    try:
        parsed_response = re.findall(r"[Tt]he score is \[(Correct|Incorrect)\]", response)[0]
        if parsed_response == "Correct":
            return 1
        elif parsed_response == "Incorrect":
            return 0
        return -1
    except Exception:
        if "incorrect" in str(response).lower():
            return 0
        elif "correct" in str(response).lower():
            return 1
        return -1


def parse_llama_questions(response: str | None) -> str | int | bool | None:
    if response is None:
        return -1
    try:
        parsed_response = re.findall(r"[Tt]he score is \[(Correct|Incorrect)\]", response)
        if len(parsed_response) > 0 and parsed_response[0] == "Correct":
            return 1
        elif len(parsed_response) > 0 and parsed_response[0] == "Incorrect":
            return 0
        elif "incorrect" in response.lower():
            return 0
        elif "correct" in response.lower():
            return 1
        else:
            return -1
    except Exception:
        return -1


def parse_trivia_qa(response: str | None) -> str | int | bool | None:
    if response is None:
        return -1
    try:
        eval_js = ast.literal_eval(response[7:-3])
    except Exception:
        eval_js = ast.literal_eval(response)
    assert "analysis" in eval_js and "judgment" in eval_js and eval_js["judgment"]
    result = eval_js["judgment"]
    if result == "correct":
        return 1
    elif result == "incorrect":
        return 0
    else:
        return -1


def parse_math_qa(response: str | None) -> int:
    if response is None:
        return -1
    response = normalize_text(response.strip().splitlines()[0].strip())
    if not response:
        return -1
    if response == "yes":
        return 1
    if response == "no":
        return 0
    return -1



