#: Sampling temperature per judge kind. ``LLMClient.temperature`` defaults to 1.0; only
#: ``OpenAudioBenchLLMJudge.__init__`` sets 0.0 (its ``top_p`` is set too but never sent by ``generate``).
#: The Gemma-routed judges (HaluEval, keyword, math) share ``KeywordLLMJudge().llm`` and so sample at 1.0.
JUDGE_TEMPERATURE = {"trivia_qa": 0.0, "llama_questions": 0.0, "simple_qa": 1.0, "math_qa": 1.0, "keyword": 1.0}

#: ``LLMJudge.max_retries`` and the ``max_new_tokens`` it passes to ``LLMClient.generate``.
MAX_RETRIES = 3
MAX_NEW_TOKENS = 512


def first_line(content: Optional[str]) -> str:
    """``LLMClient.generate``'s post-processing of a chat completion: strip, keep the FIRST LINE only;
    None/empty content -> ""."""
    if content:
        content = content.strip()
        content = content.split("\n")[0]
    else:
        content = ""
    return content


def run_judge(generate, kind: str, question_text: str, answer_text: str, gt_answers: Optional[List[str]] = None):
    """``LLMJudge.__call__`` for judge ``kind``. ``generate(prompt, temperature, max_new_tokens) -> str`` must
    return :func:`first_line` of the reply. Returns the parser's value (1 / 0 / -1, or a keyword), or None when
    the question or answer is empty or every attempt raised -- upstream's summary drops both None and -1."""
    template, parser = JUDGES[kind]
    if not answer_text or not question_text:
        return None
    prompt = template.format(
        question=question_text,
        answer=answer_text,
        valid_answers=str(gt_answers) if gt_answers else "",
    )
    result = None
    for _ in range(MAX_RETRIES):
        try:
            response = generate(prompt, JUDGE_TEMPERATURE[kind], MAX_NEW_TOKENS)
            assert response is not None and response.strip() != "", (
                f"response: '{response}' is None or empty for {prompt}"
            )
            result = parser(response)
            break
        except Exception:
            continue
    return result


def tail_stop_length(model_text: List[str], question_end_step: int, max_tail_silence: int) -> Optional[int]:
    """How many ``model_text`` pieces upstream's inference loop keeps before it stops.

    ``InferenceJob._check_tail_silence`` runs after every output step once the question is fed: counting from
    index ``question_end_step``, it finalizes as soon as MORE than ``max_tail_silence`` consecutive pieces are
    ``"<pad>"``. Generation only continues on silent input, so stopping early and truncating a longer capture
    at the same step are the same transcript. Returns the kept length, or None if the stop never fired within
    ``model_text`` (the capture ended first).
    """
    consecutive = 0
    for i, piece in enumerate(model_text):
        if i < question_end_step:
            continue
        if piece == "<pad>":
            consecutive += 1
            if consecutive > max_tail_silence:
                return i + 1
        else:
            consecutive = 0
    return None
